import java.util.Scanner;

public class Main {
    public static void main(String[] args) {
        Scanner scanner = new Scanner(System.in);
        long x = scanner.nextLong();
        long y = scanner.nextLong();
        long n = scanner.nextLong();
        long num = 0;
        long den = 1;

        for (long i = 1; i <= n; i++) {
            long candidate1 = (i * x) / y;
            long candidate2 = candidate1 + 1;

            // Check function equivalent
            check(candidate1, i);
            check(candidate2, i);

            void check(long val, long idx) {
                long diffA = Math.abs((den * y) * ((x * idx) - (y * val)));
                long diffB = Math.abs((y * idx) * ((den * x) - (num * y)));
                if (diffA < diffB || (diffA == diffB && idx < den)) {
                    den = idx;
                    num = val;
                }
            }
        }
        System.out.println(num + "/" + den);
        scanner.close();
    }
}

